<script>document.addEventListener('DOMContentLoaded',function(){const b=document.querySelector('.menu-toggle'),n=document.getElementById('store-nav'),c=document.querySelector('.nav-category-button'),m=document.getElementById('category-menu');if(b&&n)b.addEventListener('click',function(e){e.stopPropagation();const open=n.classList.toggle('open');b.setAttribute('aria-expanded',open?'true':'false');});if(c&&m)c.addEventListener('click',function(e){e.stopPropagation();const open=m.classList.toggle('show');c.setAttribute('aria-expanded',open?'true':'false');});document.addEventListener('click',function(){if(m)m.classList.remove('show');if(c)c.setAttribute('aria-expanded','false');});});</script>
